mroz_lw <- mroz[!is.na(mroz$lwage), ]
nls_cc <- nlswork[complete.cases(
  nlswork[, c("ln_wage", "grade", "age", "ttl_exp", "tenure")]
), ]

# --- Fixture path helper ---
hf_path <- function(ds, kind, hnn) {
  fixture_path(sprintf("hf_%s_%s_%s.csv", ds, kind, hnn))
}

# --- Sentinels: one per dataset block, keyed on the first fixture written ---
have_hf_gril <- file.exists(hf_path("gril", "coef", "H03"))
have_hf_mroz <- file.exists(hf_path("mroz", "coef", "H31"))
have_hf_phil <- file.exists(hf_path("phil", "coef", "H79"))
have_hf_ab <- file.exists(hf_path("ab", "coef", "H89"))
have_hf_grun <- file.exists(hf_path("grun", "coef", "H95"))
have_hf_nls <- file.exists(hf_path("nls", "coef", "H103"))

# Name translation (Stata term -> canonical R term label) uses the shared translate_stata_xi_names() helper (helper-fixtures.R); griliches uses `xi i.year`, generating `_Iyear_NN` dummies, and everything else maps 1:1 except the constant.

# ============================================================================
# Diagnostics field mapping: Stata e()-style column name -> R fit accessor
# ============================================================================

.hf_diag_value <- function(fit, col) {
  d <- fit$diagnostics
  switch(col,
    r2       = fit$r.squared,
    r2_a     = fit$adj.r.squared,
    r2u      = fit$r2u,
    r2c      = fit$r2c,
    rss      = fit$rss,
    rmse     = fit$sigma,
    F_stat   = fit$model_f,
    F_p      = fit$model_f_p,
    F_df1    = fit$model_f_df1,
    F_df2    = fit$model_f_df2,
    sargan   = if (!is.null(d$overid)) d$overid$stat else NA_real_,
    sarganp  = if (!is.null(d$overid)) d$overid$p else NA_real_,
    sargandf = if (!is.null(d$overid)) d$overid$df else NA_real_,
    j        = if (!is.null(d$overid)) d$overid$stat else NA_real_,
    jp       = if (!is.null(d$overid)) d$overid$p else NA_real_,
    jdf      = if (!is.null(d$overid)) d$overid$df else NA_real_,
    idstat   = if (!is.null(d$underid)) d$underid$stat else NA_real_,
    idp      = if (!is.null(d$underid)) d$underid$p else NA_real_,
    iddf     = if (!is.null(d$underid)) d$underid$df else NA_real_,
    cdf      = if (!is.null(d$weak_id)) d$weak_id$stat else NA_real_,
    widstat  = if (!is.null(d$weak_id_robust)) d$weak_id_robust$stat
               else if (!is.null(d$weak_id)) d$weak_id$stat else NA_real_,
    arf      = if (!is.null(d$anderson_rubin)) d$anderson_rubin$f_stat
               else NA_real_,
    arfp     = if (!is.null(d$anderson_rubin)) d$anderson_rubin$f_p
               else NA_real_,
    archi2   = if (!is.null(d$anderson_rubin)) d$anderson_rubin$chi2_stat
               else NA_real_,
    archi2p  = if (!is.null(d$anderson_rubin)) d$anderson_rubin$chi2_p
               else NA_real_,
    ardf     = if (!is.null(d$anderson_rubin)) d$anderson_rubin$f_df1
               else NA_real_,
    ardf_r   = if (!is.null(d$anderson_rubin)) d$anderson_rubin$f_df2
               else NA_real_,
    cstat    = if (!is.null(d$orthog)) d$orthog$stat else NA_real_,
    cstatp   = if (!is.null(d$orthog)) d$orthog$p else NA_real_,
    cstatdf  = if (!is.null(d$orthog)) d$orthog$df else NA_real_,
    sstat    = if (!is.null(d$stock_wright)) d$stock_wright$stat else NA_real_,
    sstatp   = if (!is.null(d$stock_wright)) d$stock_wright$p else NA_real_,
    sstatdf  = if (!is.null(d$stock_wright)) d$stock_wright$df else NA_real_,
    estat    = if (!is.null(d$endogeneity)) d$endogeneity$stat else NA_real_,
    estatp   = if (!is.null(d$endogeneity)) d$endogeneity$p else NA_real_,
    estatdf  = if (!is.null(d$endogeneity)) d$endogeneity$df else NA_real_,
    redstat  = if (!is.null(d$redundancy)) d$redundancy$stat else NA_real_,
    redp     = if (!is.null(d$redundancy)) d$redundancy$p else NA_real_,
    reddf    = if (!is.null(d$redundancy)) d$redundancy$df else NA_real_,
    N_clust  = fit$n_clusters %||% NA_real_,
    N_clust1 = fit$n_clusters1 %||% NA_real_,
    N_clust2 = fit$n_clusters2 %||% NA_real_,
    NA_real_
  )
}

# Columns with no direct R-side equivalent among the fitted models in this
# fixture set: K/L are the .do file's own rankxx/rankzz bookkeeping (not a
# fit quantity); kclass/lambda/fuller/arubin* apply only to LIML-family
# fits, none of which appear here (the help file's LIML examples are all on
# klein, covered by test-ts-operators.R) — confirmed always missing in every
# hf_*_diagnostics_*.csv fixture, so the comparison loop never reaches them.
.hf_diag_skip <- c("K", "L", "kclass", "lambda", "fuller",
                    "arubin", "arubinp", "arubin_lin", "arubin_linp",
                    "arubindf")
.hf_diag_exact <- c("F_df1", "F_df2", "jdf", "sargandf", "iddf", "ardf",
                     "ardf_r", "cstatdf", "sstatdf", "estatdf", "reddf",
                     "N_clust", "N_clust1", "N_clust2")
.hf_diag_pval <- c("F_p", "jp", "sarganp", "idp", "arfp", "archi2p",
                    "sstatp", "estatp", "cstatp", "redp")

# ============================================================================
# compare_hf(): coefficients + SEs, full VCV, and every non-missing
# diagnostics column against a Stata help-file fixture set.
# ============================================================================

compare_hf <- function(fit, ds, hnn, tol_coef = stata_tol$coef,
                       tol_se = stata_tol$se) {
  # --- Coefficients and SEs ---
  coef_fx <- read.csv(hf_path(ds, "coef", hnn), stringsAsFactors = FALSE)
  coef_fx$term_r <- translate_stata_xi_names(coef_fx$term)
  b <- coef(fit)
  se <- sqrt(diag(vcov(fit)))
  testthat::expect_setequal(coef_fx$term_r, names(b))
  for (i in seq_len(nrow(coef_fx))) {
    nm <- coef_fx$term_r[i]
    testthat::expect_equal(unname(b[nm]), coef_fx$estimate[i],
                           tolerance = tol_coef,
                           info = paste(ds, hnn, "coef", nm))
    testthat::expect_equal(unname(se[nm]), coef_fx$std_error[i],
                           tolerance = tol_se,
                           info = paste(ds, hnn, "se", nm))
  }

  # --- Full VCV ---
  vcov_fx <- read.csv(hf_path(ds, "vcov", hnn))
  vcov_cols <- grep("^vcov_", names(vcov_fx), value = TRUE)
  V_s <- as.matrix(vcov_fx[, vcov_cols, drop = FALSE])
  stata_terms <- translate_stata_xi_names(sub("^vcov_", "", vcov_cols))
  dimnames(V_s) <- list(stata_terms, stata_terms)
  V_r <- vcov(fit)
  testthat::expect_setequal(rownames(V_r), stata_terms)
  expect_vcov_equal(V_r, V_s)

  # --- Diagnostics: every non-missing column ---
  dx <- read_diagnostics(hf_path(ds, "diagnostics", hnn))
  testthat::expect_identical(fit$nobs, as.integer(dx$N))

  for (col in names(dx)) {
    if (col %in% .hf_diag_skip) next
    val <- dx[[col]]
    if (is.na(val)) next

    r_val <- .hf_diag_value(fit, col)
    if (is.na(r_val)) {
      # Two distinct reasons a Stata quantity has no R counterpart here:
      # (1) pure-OLS-via-ivreg2 models (no instrument structure at all,
      #     e.g. H90/H92) post no overid diagnostic (fit$diagnostics$overid
      #     is NULL) where Stata prints the exact-identification
      #     placeholder j=0/jdf=0 -- both mean "no overid test", agreement.
      # (2) genuinely not applicable to this fit; skip silently (mirrors
      #     validate-helpfile.qmd's compare_fixture() "skip" bucket).
      if (col %in% c("j", "jdf", "sargan", "sargandf") && val == 0) {
        testthat::expect_null(fit$diagnostics$overid,
                              info = paste(ds, hnn, col, "(exactly identified)"))
      }
      next
    }

    if (col %in% .hf_diag_exact) {
      testthat::expect_equal(round(r_val), round(val),
                             info = paste(ds, hnn, col))
    } else if (col %in% .hf_diag_pval) {
      testthat::expect_equal(r_val, val, tolerance = stata_tol$pval,
                             info = paste(ds, hnn, col))
    } else {
      testthat::expect_equal(r_val, val, tolerance = stata_tol$stat,
                             info = paste(ds, hnn, col))
    }
  }
}


