  gril_h07_fit <<- fit
})

test_that("H11: Griliches GMM2S + robust + user smatrix (help.txt:1162-1174)", {
  skip_if(!have_hf_gril, "helpfile fixtures not found")
  skip_if(is.null(gril_h07_fit), "H07 fit unavailable")
  e <- residuals(gril_h07_fit)
  Z <- model.matrix(gril_h07_fit, component = "instruments")
  n <- nobs(gril_h07_fit)
  S <- crossprod(Z * as.numeric(e)) / n
  fit <- ivreg2(
    lw ~ s + expr + tenure + rns + smsa + factor(year) | iq | med + kww + age + mrt,
    data = griliches, method = "gmm2s", vcov = "robust", smatrix = S
  )
  compare_hf(fit, "gril", "H11")
})

test_that("H13: Griliches GMM2S + robust + user wmatrix (help.txt:1178-1182)", {
  skip_if(!have_hf_gril, "helpfile fixtures not found")
  skip_if(is.null(gril_h07_fit), "H07 fit unavailable")
  e <- residuals(gril_h07_fit)
  Z <- model.matrix(gril_h07_fit, component = "instruments")
  n <- nobs(gril_h07_fit)
  S <- crossprod(Z * as.numeric(e)) / n
  W <- solve(S)
  fit <- ivreg2(
    lw ~ s + expr + tenure + rns + smsa + factor(year) | iq | med + kww + age + mrt,
    data = griliches, method = "gmm2s", vcov = "robust", wmatrix = W
  )
  compare_hf(fit, "gril", "H13")
})

