test_that("H27: Griliches cluster(year) (help.txt:1250)", {
  skip_if(!have_hf_gril, "helpfile fixtures not found")
  # M = 7 year clusters vs L = 15 instruments: both Stata and R leave the
  # Hansen J and Stock-Wright statistics missing (singular cluster-robust
  # moment covariance), while still reporting the test's df -- confirmed by
  # the fixture (hf_gril_diagnostics_H27.csv: jdf populated, j blank). The
  # warnings are therefore expected, not a bug; this is the help file's own
  # example, verbatim.
  expect_warning(
    expect_warning(
      fit <- ivreg2(
        lw ~ s + expr + tenure + rns + smsa + factor(year) | iq | med + kww + age,
        data = griliches, clusters = ~year
      ),
      "Hansen J statistic not computed"
    ),
    "Stock-Wright.*rank-deficient"
  )
  compare_hf(fit, "gril", "H27")
})

test_that("H28: Griliches cluster(year) + partial(year dummies) (help.txt:1253)", {
  skip_if(!have_hf_gril, "helpfile fixtures not found")
  # Same M = 7 vs L = 15 singularity as H27 (partialling out the year
  # dummies does not change the cluster/instrument count).
  expect_warning(
    expect_warning(
      fit <- ivreg2(
        lw ~ s + expr + tenure + rns + smsa + factor(year) | iq | med + kww + age,
        data = griliches, clusters = ~year, partial = "factor(year)"
      ),
      "Hansen J statistic not computed"
    ),
    "Stock-Wright.*rank-deficient"
  )
  compare_hf(fit, "gril", "H28")
})


