# H91 (cluster(id)) and H92 (bw(8) + truncated + robust) are NOT asserted
# equal here: help-file-specs.md and validate-helpfile.qmd document them as
# two separate salvaged examples of the SAME bw(9) help-file bug, and
# neither source claims H91 == H92. They are different estimators in
# general, coinciding only when the kernel-implied bandwidth spans the full
# within-panel timespan. bw(8) IS that full-span case for abdata (T = 9),
# and the coincidence is asserted on provable grounds in
# test-vcov-cluster-kernel.R ("cluster-robust equals robust truncated
# kernel at maximum bandwidth"); it stays unasserted here because no
# help-file source states it.


# ============================================================================
# Documented divergences
# ============================================================================

test_that("H22: Griliches CUE robust converges to Stata's basin (flat-objective cell)", {
  # The CUE ratio objective on this 13-regressor model has its minimum in a
  # degenerate basin (R^2 = -54, J = 40.1) -- the documented ratio-objective
  # pathology of the CUE ESTIMATOR (Hausman et al. 2011), not an optimizer
  # bug. Stata's Newton-Raphson has always found it. Before the parscale fix,
  # R's unscaled BFGS stalled at its iteration cap at J = 67.5, and that stall
  # was recorded as an "intentional divergence". With
  # per-coordinate scaling, BFGS genuinely converges (code 0) into the same
  # basin as Stata (a 600-random-direction probe at relative radii 1e-3 to
  # 1e-1 found zero descent directions at the optimum; the old point had 55
  # of 200 -- it was not a critical point at all). The basin is extremely
  # flat, so coefficient agreement with the fixture is limited to flat-basin
  # resolution (observed max 0.74% relative; a ~9e-8 relative change in J
  # moves coefficients by ~0.3%) -- but J itself varies across the basin at
  # only that ~1e-7 relative scale, so J IS a full parity quantity here
  # even though the coefficients are not. The bands below assert BASIN
  # MEMBERSHIP for the coordinates: the old stall point and the
  # economically sensible GMM2S-like basin (iq about -0.0014, R^2 = 0.37)
  # sit far outside them.
  skip_if(!have_hf_gril, "helpfile fixtures not found")
  fx <- read.csv(hf_path("gril", "coef", "H22"), stringsAsFactors = FALSE)
  fx$term_r <- translate_stata_xi_names(fx$term)
  h22_formula <-
    lw ~ s + expr + tenure + rns + smsa + factor(year) | iq | med + kww + age + mrt

  expect_no_warning(
    fit <- ivreg2(h22_formula, data = griliches, method = "cue", vcov = "robust")
  )
  # (a) Hansen J parity against Stata's own e(j) at standard tolerance --
  # the exact basin identifier (observed gap 8.7e-8 relative, ~1000x margin;
  # the pre-parscale stall point sits 27 J-units = 68% away). R's b0
  # evaluation of the CUE objective at Stata's fixture coefficients
  # reproduces this e(j) to ~1e-11, so the two implementations' J
  # computations agree at the same beta (2026-07-06 second-opinion check).
  dx <- read_diagnostics(hf_path("gril", "diagnostics", "H22"))
  expect_equal(fit$diagnostics$overid$stat, dx$j, tolerance = stata_tol$stat)
  expect_equal(fit$diagnostics$overid$p, dx$jp, tolerance = stata_tol$pval)
  # (b) coefficients and SEs agree with Stata at flat-basin resolution.
  # Band derivation: coordinate displacement near a quadratic minimum scales
  # as sqrt of the objective gap, so a cross-platform J agreement of ~1e-6
  # relative (vs the 9e-8 observed here) predicts ~sqrt(1e-6/9e-8) * 0.74%
  # ~ 2.5% spread; 5% covers that while staying ~20x inside the iq
  # separation from the other basin (|iq_other - iq_fx|/|iq_fx| ~ 99.5%).
  b_r <- coef(fit)[fx$term_r]
  se_r <- sqrt(diag(vcov(fit)))[fx$term_r]
  expect_lt(max(abs(unname(b_r) - fx$estimate) / abs(fx$estimate)), 0.05)
  expect_lt(max(abs(unname(se_r) - fx$std_error) / abs(fx$std_error)), 0.05)
  # (c) the degenerate-basin signature: negative R^2 (the sensible basin has
  # R^2 = 0.37). For the two known basins this is implied by (a) -- R^2 is a
  # function of beta -- and is kept as self-documenting belt-and-suspenders
  # that survives any future loosening of the J band.
  expect_lt(fit$r.squared, 0)
})

test_that("H90/H92: bw(9) is rejected by both Stata and R (help.txt:1551/1561)", {
  # T = 9 (abdata timespan); bw() must be strictly less than the panel's
  # timespan, so bw(9) leaves no valid lag structure for the truncated
  # kernel. bw(8) (max lag = T - 1 = 8) is numerically identical because
  # the truncated kernel assigns weight 1 to every available lag -- see the
  # H90/H92 tests above for the salvaged bw(8) fixture comparisons. Both
  # Stata (r(198): "bandwidth cannot exceed timespan of data") and R reject
  # the help file's own command.
  expect_error(
    ivreg2(n ~ w + k, data = abdata, kernel = "truncated", bw = 9,
           tvar = "year", ivar = "id"),
    "time span"
  )
  expect_error(
    ivreg2(n ~ w + k, data = abdata, kernel = "truncated", bw = 9,
           vcov = "robust", tvar = "year", ivar = "id"),
    "time span"
  )
})

test_that("H29: partial + gmm2s is infeasible (help.txt:1261)", {
  # After partialling out the year dummies, 5 included + 3 excluded = 8
  # moment conditions remain against M = 7 year clusters, so the
  # cluster-robust S matrix has rank <= 7 < 8 and cannot be inverted. Stata
  # itself rejects this command (r(506): "optimal GMM weighting matrix not
  # unique"; see generate-helpfile-fixtures.do's `assert _rc != 0` for H29).
  expect_error(
    ivreg2(
      lw ~ s + expr + tenure + rns + smsa + factor(year) | iq | med + kww + age,
      data = griliches, clusters = ~year, partial = "factor(year)",
      method = "gmm2s"
    ),
    "not of full rank"
  )
})
